"""
小说检察官 ——《镇冢秘术》机械初检 + AI 人工复核双闸。

检察官可从任意工作目录启动，始终从脚本所在项目的 `正文/`读取全部现有章节，
并以 `设定/00_镇冢秘术_唯一总圣经.md`为唯一剧情权威，从
`设定/canon事实库.json`读取它的机器镜像。两者 CANON-ID 不同或任一
缺失或损坏，程序会拒绝体检，不允许用内嵌旧规则产生“缺库假全绿”。

常用命令：
  python3 工具/小说检察官.py             # 全部现有章节
  python3 工具/小说检察官.py 71          # 第71章（文件存在时）
  python3 工具/小说检察官.py --末章 410  # 末章硬闸单跑（封版 --前／--後）
  python3 工具/小说检察官.py --十一轮 410  # 第十一轮之凭
  python3 工具/小说检察官.py --selftest  # 规则自检 + 项目接线自检
  python3 工具/小说检察官.py --doctor    # 查路径/canon/章号/文档/阅读器接线

正文修改后先运行 `python3 工具/同步全本阅读器.py`，再运行检察官；检察官本身
只做阅读器 `--check`，不会自动改 HTML。
"""
