READER_SYNC = os.path.join(REPO_ROOT, '工具', '同步全本阅读器.py')
DENSE = 5  # 单句逗号 >= 这个数,算"顿得偏碎"

# ―― 分量反向闸(2026-07-17 作者令：机器从此咬"薄"，和咬"错"一样狠) ――
MIN_CHARS_NEW = 2000      # 唯一铁底(2026-07-22作者令:2500旧线拆除,严禁为线凑字);豁免通道保留
MIN_CHARS_REVIEW = 2000   # 复核层与铁底同线(旧2300拆除)
LONG_PARA_CHARS = 120     # "长段"=一段跑起来的持续描写
WEIGHT_FROM_CH = 73
_BUILD_CACHE = {}
def _chapter_body(t):
    t=t.split('【本章亮点】')[0]
    return re.sub(r'^.*?第.+?章[^\n]*\n','',t,count=1,flags=re.S)
def _weight_stats(t):
    body=_chapter_body(t)
    paras=[re.sub(r'\s','',p) for p in body.split('\n') if p.strip() and p.strip()!='＊']
    chars=sum(len(p) for p in paras)
    longp=sum(1 for p in paras if len(p)>=LONG_PARA_CHARS)
    return chars,len(paras),longp
def rhythm_stats(text):
    """段长分位与长段数。【批119】节奏方差之量器。"""
    ps = [re.sub(r'\s', '', x) for x in _chapter_body(text).split('\n')
          if x.strip() and x.strip() != '＊']
    L = sorted(len(x) for x in ps)
    if not L:
        return 0, 0, 0.0
    p90 = L[int(len(L) * 0.9)] if len(L) > 1 else L[0]
    long120 = sum(1 for x in L if x >= LONG_PARA_CHARS)
    r60 = 100.0 * sum(1 for x in L if x >= 60) / len(L)
    return p90, long120, r60


def rhythm_violation(text, n, exempt=False):
    """【批119·节奏方差闸】第153章起为硬错，其前为REVIEW。
    立法之据（全书实测）：段长90分位 1-30章91字→61-90章56→121-152章28；
    ≥60字段占比 25.7%→8.8%→0.3%；单句段占比 34.2%→50.4%→71.0%。
    塌的不是均值是方差：近三十章九成段落短于28字，一章之内几无换气处。
    病不在短在齐——招使成了唯一的招，就不再是招，是底噪（P26）。
    判：段长90分位≥30字（硬）；「至少一处≥120字之长段」只作 REVIEW，见 rhythm_review。
    〔1119 死规之审·gates13〕长段之底降为 REVIEW：293—297 为过此闸补长段、并拍；作者 F087 原级即 REVIEW。90分位留硬（坑⑯·208）。
    豁免：施工表登记「第 N 章节奏豁免」并写明理由。"""
    if n < 153 or exempt:
        return None
    p90, long120, r60 = rhythm_stats(text)
    bad = []
    # 〔1119 死规之审·gates13〕「无一段≥120字」⛔入 bad（归 rhythm_review 之 REVIEW），只 90 分位之塌入硬错
    if p90 < 30:
        bad.append('段长90分位仅%d字(<30)' % p90)
    if not bad:
        return None
    # 〔1119 死规之审·gates13〕报文去「每章须至少一处长段」之配额语，留 90 分位与豁免之门
    return ('节奏方差塌缩:%s;≥60字段占比%.1f%% —— 全章切成一样长的碎拍即病,段长90分位须≥30字'
            '(P26/批119);缝出来的不算(拆回单句独行若读来无异即为缝的);'
            '确属例外须在施工表登记"第 %d 章节奏豁免"并说明理由'
            % ('、'.join(bad), r60, n))


def rhythm_review(text, n, exempt=False):
    """〔1119 死规之审·gates13〕「无一段≥120字」只作 REVIEW 之信号：印之、⛔入 bad／pr（长段随事而生，⛔为过闸补之）。
    REVIEW 之数由旧复核层 check_file 之「[分量] 全章没有一段≥120字」计入。"""
    if n < 153 or exempt:
        return None
    p90, long120, r60 = rhythm_stats(text)
    if long120 >= 1:
        return None
    return ('REVIEW·节奏:无一段≥%d字(段长90分位%d字、≥60字段占比%.1f%%)——只是信号,不计硬错;'
            '长段该来时别削,⛔为过闸补长段' % (LONG_PARA_CHARS, p90, r60))


def _rhythm_exempt(n):
    if 'txt' not in _BUILD_CACHE:
        try:
            _BUILD_CACHE['txt'] = open(_os.path.join(REPO_ROOT, '设定/01_镇冢秘术_逐章施工与伏笔回收表.md'), encoding='utf-8').read()
        except OSError:
            _BUILD_CACHE['txt'] = ''
    return bool(re.search(rf'第\s*{n}\s*章节奏豁免', _BUILD_CACHE['txt']))


def _short_ch_exempt(n):
    if 'txt' not in _BUILD_CACHE:
        try: _BUILD_CACHE['txt']=open(os.path.join(REPO_ROOT,'设定/01_镇冢秘术_逐章施工与伏笔回收表.md'),encoding='utf-8').read()
        except OSError: _BUILD_CACHE['txt']=''
    return bool(re.search(rf'第\s*{n}\s*章短章豁免',_BUILD_CACHE['txt']))

def _receipt_files(n):
    """★体检账 九十九／一〇〇 之治（限351·本章落地）：以**档名**认它是谁的回执。
    ⛔不许再拿「文书里提到过第N章」当凭——一份讲闸的文书曾替第73、74两章过了回执闸。"""
    out=[]
    for fp in glob.glob(os.path.join(REPO_ROOT,'设定','回执_*.md')):
        if re.search(rf'第\s*{n}\s*章',os.path.basename(fp)): out.append(fp)
    return out

def _receipt_ok(n):
    """回执闸:第73章起,当章检察官回执须已归档(档名认章 + 伏笔+逐项)。"""
    tx=''
    for fp in _receipt_files(n):   # 一章之回执可分数档（作业单／封版席），合而查之
        try: tx+=open(fp,encoding='utf-8').read()
        except OSError: continue
    if True:
        # 〔1119 死规之审·gates14〕拔「五钩」之键（与 封版.回执闸之键 同拔）：逐章逼答钩，坐实「每章须有钩」之框；只拔不加，旧回执⛔重红
        if ('伏笔' in tx
                and (n<76 or '新锚' in tx) and (n<78 or ('病历' in tx and '清单' in tx and '原场' in tx))
                and (n<81 or '到期账' in tx)
                and (n<82 or ('章魂' in tx and '生死检' in tx and '改动闸' in tx))
                # ★体检账 九十九 之治（限351）：把「本章之失」那一行接回回执之链。
                #   ⛔自 351 起索之——往回不追溯，免得拿新索去红两个月前的旧章。
                and (n<351 or '本章之失' in tx)):
            return True
    return False


_PROPS = ['铃','马灯','胸灯','背架','衔木','铜针','拓片','刀','布条','鸡蛋','油壶','本子','玉']


def diff_gate(n, base="HEAD"):
    """改动闸：拿本章与git上一版做diff，只查变动段及其左右邻段——新伤只长在缝口上。"""
    import subprocess as _sp
    fs=_chapters()
    if n not in fs: print('  ✗未找到第%d章正文'%n); return 1
    fp=fs[n][0]
    rel=os.path.relpath(fp,REPO_ROOT)
    try:
        old=_sp.run(['git','show',base+':'+rel],cwd=REPO_ROOT,capture_output=True,text=True).stdout
    except Exception as e:
        print('  ✗取上一版失败:',e); return 1
    if not old.strip():
        print('  ℹ本章为新增章，无上一版可比，改动闸跳过'); return 0
    new=open(fp,encoding='utf-8').read()
    ob=[x.strip() for x in old.split('【本章亮点】')[0].split('\n') if x.strip()]
    nb=[x.strip() for x in new.split('【本章亮点】')[0].split('\n') if x.strip()]
    oset=set(ob)
    changed=[(i,x) for i,x in enumerate(nb) if x not in oset]
    # 【批123·订】原此闸只认「新增之段」为变动：纯删段时 changed 为空，遂报「无文本变动」而放行。
    #   ★而删段之缝口正是新伤最爱长的地方（上下二段本不相邻，删掉中间那一段，它们就直接接上了）；
    #   ★★而220、222第10轮连着两回皆为「处死三段」，此闸连着两回报「无文本变动」。
    #   ★★★而我两回都把它记成「删段之前未先存版」之序错——★★★★其实序不序都一样，此闸看不见删。
    # 治：并算「删掉之段」，以其在新文中的接缝处为变动位，照样查缝口。
    nset = set(nb)
    deleted = [x for x in ob if x not in nset]
    if deleted and not changed:
        # 纯删段：找出每一处删口在新文中的位置（删掉那一段的前一段之后）
        seams = []
        for i, x in enumerate(ob):
            if x in nset:
                continue
            prev = next((ob[j] for j in range(i - 1, -1, -1) if ob[j] in nset), None)
            if prev is not None and prev in nb:
                seams.append((nb.index(prev), prev))
        changed = seams
        print('\n  ℹ本轮为纯删段（删 %d 段）：以删口为变动位查缝口。' % len(deleted))
    print('\n'+'█'*3+' 改动闸 · 第%d章（只查缝口·新伤只长在这里） '%n+'█'*3)
    print('  段数 %d → %d ；变动段 %d'%(len(ob),len(nb),len(changed)))
    if not changed:
        print('  ✓ 本章较上一版无文本变动'); return 0
    idxs=set()
    for i,_ in changed:
        for j in (i-1,i,i+1):
            if 0<=j<len(nb): idxs.add(j)
    zone='\n'.join(nb[j] for j in sorted(idxs))
    bad=0
    _rn, _rl = rel_day_check(n, new)
    if _rl:
        for _x in _rl:
            print(_x)
    print('\n  ── 一·机械层（仅变动段及左右邻段） ──')
    for name,pat in [('破折号','—'),('半角逗号',','),('英文',r'[A-Za-z]'),
                     ('抖族','哆嗦|颤'),('永禁机制词','点亮|鼎心|气运|换锚|阵眼'),('骊山僵尸','骊山|僵尸')]:
        m=re.findall(pat,zone)
        if m: bad+=len(m); print('    ⛔%s×%d'%(name,len(m)))
    five=[s.strip() for s in re.split(r'(?<=[。！？…])',zone) if s.count('，')>=5]
    for s in five: bad+=1; print('    ⛔五逗:',s[:40])
    print('    %s'%('✓机械层干净' if bad==0 else '⛔机械层%d处，必须清零'%bad))
    print('\n  ── 二·自造重复（新增四字串在本章他处已有） ──')
    rest=''.join(x for i,x in enumerate(nb) if i not in [k for k,_ in changed])
    rep=[]
    for _,x in changed:
        for k in range(len(x)-3):
            g4=x[k:k+4]
            if re.fullmatch(r'[\u4e00-\u9fff]{4}',g4) and rest.count(g4)>=1 and g4 not in rep:
                rep.append(g4)
    print('    '+('⚠疑似自造重复：'+ '、'.join(rep[:8]) if rep else '✓无'))
    print('\n  ── 三·悬空指代（变动段首句以代词起，须查先行词） ──')
    dang=[x[:26] for _,x in changed if re.match(r'^[他她它那这]',x)]
    print('    '+('⚠须查先行词：'+' ｜ '.join(dang[:6]) if dang else '✓无'))
    print('\n  ── 四·器物动线（变动段涉及之器物，全章出现处须逐一对齐） ──')
    hit=[pn for pn in _PROPS if any(pn in x for _,x in changed)]
    for pn in hit:
        cnt=sum(1 for x in nb if pn in x)
        print('    ▣ %s：本章共%d处 —— 逐处核对位置与归属（P18处方）'%(pn,cnt))
    if not hit: print('    ✓变动段未涉器物')
    print('\n  ── 五·数字冲突（变动段中的数，与全章同类数对表） ──')
    nums=sorted(set(re.findall(r'[一二三四五六七八九十百千两]{1,4}(?:息|步|根|道|尺|天|回|声|指|寸|丈)',''.join(x for _,x in changed))))
    print('    '+('▣ '+ '、'.join(nums) +' —— 逐个与全章及前章对表' if nums else '✓变动段无数字'))
    print('\n  ── 五·五·章号泄漏（第一人称正文不得出现章号） ──')
    _bd=re.sub(r'^.*?第.+?章[^\n]*\n','',new.split('【本章亮点】')[0],count=1,flags=re.S)
    _ln=re.findall(r'[一二三四五六七八九十百]+章',_bd)
    if _ln: bad+=len(_ln); print('    ⛔章号入正文×%d:'%len(_ln), '、'.join(_ln[:5]), '（叙述者不可能说出章号＝作者出画）')
    else: print('    ✓无')
    print('\n  ── 六·五·亮点段专检（P19：改正文必重写亮点段，重写必先自检） ──')
    _h=new[new.find('【本章亮点】'):] if '【本章亮点】' in new else ''
    if not _h:
        print('    ⚠本章无亮点段')
    else:
        _b1=_h.count('—'); _b2=sum(1 for s in re.split(r'(?<=[。！？…])',_h) if s.count('，')>=5); _b3=_h.count(',')
        print('    破折%d／五逗句%d／半角逗%d  %s'%(_b1,_b2,_b3,'✓' if _b1+_b2+_b3==0 else '⛔亮点段未清零，禁同步'))
        if _b1+_b2+_b3: bad+=_b1+_b2+_b3
    print('\n  ── 六·段间空行（变动区） ──')
    # 批131：此闸原查全文，而【本章亮点】係markdown列行，行行紧挨本就无空行；
    # 故全书292章中55章长红，且其白文内命中皆为0——一个只会假红的闸，教出来的是「看见红就跳过」。
    # 段间空行是白文之律，非亮点段之律：故只查白文。
    _bw = new.split('【本章亮点')[0]
    _lk = re.search(r'[。！？”＊]\n(?!\n)(?=[^\n])',_bw)   # ★2026-09-05 加「＊」，与 硬闸.py 同式
    print('    '+('⛔漏空行（白文·行%d）'%(_bw[:_lk.start()].count('\n')+1) if _lk else '✓无'))
    if _lk: bad += 1
    print('█'*3+' 改动闸毕：机械层%s '%('通过' if bad==0 else '未过')+'█'*3)
    return 1 if bad else 0


# ⛔1027 汰冷眼轮（大审瘦式每十章一回、盲读每章读 N-2／N-1 已代之）：旧之冷轮自派（逐章派生「第N章冷眼轮」之到期账）
#   与其转调开轮六检⑥之四判（执、废、限、无面而明裁）俱去；到期账之 COLD 行同日清。
def _load_due():
    p=os.path.join(REPO_ROOT,'设定','到期账.json')
    try: return json.load(open(p,encoding='utf-8')).get('items',[])
    except Exception: return []


# 【批123·订】原词表只认 done／废弃／cold／冷藏／已清，而不认 closed：
#   ★220判账时 PLOT-207A 记为 closed（清账章220、清账记已落），而此闸仍判它逾期2章未清；
#   ★★遂於222起草毕报 ERROR——其为词表之漏，非账之欠。
#   ★★★而 closed 是通用词且220已用，改账则日后再犯；故补机器之词表，不改账。
#   ★★★★而 half（清其半）亦当免催：其余半已另记到期章（如CHAR-191A改期228），
#     由那一章的到期账去催；此处再催一遍，催的是已经改过期的同一笔。
# 【批124·订·2026-09-04·303第1轮】词表再漏一个：账写「清」，而表只认「已清」。
#   ★其红在哪一行：`python3 工具/小说检察官.py --全书检` 於303报
#     「到期账逾期2章未清: [PRES-297A]…（限第301章）」三笔，而三笔在 设定/到期账.json 里
#     状态皆係「清」、结账章皆係301、且其「判」逐笔写着「301第13轮毕·封版之序判「清」」——
#     **账已清而闸照旧催，催的是已经还过的三笔。**
#   ★★其群（`python3 - <<EOF` 逐项数其状态）：全表 266 项，
#     done 247｜closed 9｜cold 3｜half 1｜open 3｜**清 3**——
#     **「清」只此三笔，而三笔同出於301封版那一坐**（一坐写下的一个新词，闸就跟不上）。
#   ★★★而其治照批123之例：**补机器之词表，不改账**——
#     「清」是本书判账之本字（其「判」之文自书「判「清」」），改账则日后再犯。
#   ★★★★而其验在 工具/负测_到期账词表.py：以旧表回灌那三笔须报红，新表须放行。
_CLEARED_STATES = ('done', 'closed', 'half', '废弃', 'cold', '冷藏', '已清', '清')


def due_report(cur, as_gate=False):
    """统一欠账催办：逾期1章WARN，逾期>=2章ERROR。cur=当前最新章号。"""
    items=[x for x in _load_due() if x.get('状态') not in _CLEARED_STATES]
    due=[x for x in items if x.get('到期章',10**9)<=cur]
    err=[x for x in due if cur-x['到期章']>=2]
    if not as_gate:
        print('\n████ 到期账催办（统一欠账台账） ████')
        if not due: print('  ✓ 本章无到期欠账')
        for x in due:
            lag=cur-x['到期章']
            tag='⛔逾期%d章'%lag if lag>=2 else ('⚠到期' if lag<1 else '⚠逾期1章')
            print('  %s [%s·%s] %s（立于%d章，限%d章）'%(tag,x['id'],x['类'],x['事'],x['立账章'],x['到期章']))
        if err: print('  ⛔逾期≥2章者%d项：封版门将判ERROR，必须先清账或改期并记因'%len(err))
    return err
def weight_violation(chars,ch,exempted):
    return ch>=WEIGHT_FROM_CH and chars<MIN_CHARS_NEW and not exempted

MIN_CHARS_FLOOR = 2000    # 作者铁底(只管量,不管法;2026-07-20)
MAX_CHARS_SOFT  = 10000   # 上限参考,超出仅提醒不判错

# ====================================================================
#  〔一〕机器人肚子里的"创作规范全文"——它本身就懂的全部规矩
# ====================================================================
# 〔1119 死规之审·prompts9⑦〕下第7条之旧文「少于2500字＝硬错／少于2300字亮REVIEW」改作 2000：与 MIN_CHARS_NEW／MIN_CHARS_REVIEW 及作者 0722 令一致
规范 = """# 《镇冢秘术》创作规范 & 避坑台账

> 书名《镇冢秘术》(原名《望气》,因撞名更换;书内金手指仍称"望气",两不相干)

> 这份规矩现在就长在「小说检察官」肚子里。它照着这些给稿子做体检。
> **每犯一次新错、每定一条新规，就往里加一条。** 写每一章之前之后，都拿这份清单对一遍。

## ◎ 进化守则（检察官不止是查错的，更是帮文章自主进化的）
- **三层判级，绝不一刀切：** ①铁律层（数错字数、物理反逻辑、名字泄露之类的硬错）——必须改；②过一眼层（套话、扎堆、比喻）——判词里写清"何时可留"，定夺权在作者；③建议层——凡指出问题，尽量随手给一个更优写法当参照，不强推。
- **学习闭环：** 每逮到一类新错，同一天补齐三件：规范条款＋人工必查＋（能自动就自动的）机器守卫；守卫误伤了成语、好句，就给守卫本身做精化——守卫也要讲"度"。
- **进化的目标只有一个：** 让下一章比上一章更好，而不是更"合规"。合规是底线，出彩才是目的。
> **检察官双职能：体检＋进化。** 它不只查错——每当人工抓出一类新错，当天就把这一类落成三件套（规范条款＋人工必查＋能自动就自动拦），让同类错在结构上再也发不出来。守卫本身同样受「度」的约束：误伤了成语、好句，就回炉精化（先例：字数守卫两轮精化，豁免「一个字是一个字」），坚决杜绝一刀切。

## ★、最高质量标准（每一章都按这把尺子，磨到挑不出毛病为止）
**总纲：** 每一章都拿最苛刻的眼光通读，逐句问「这句够不够亮、是不是可有可无」。目标是让读者「哇哦、舍不得放下」。能砍的废句一律砍（宁可字少，绝不注水）；不出彩的平庸句，要么重写到出彩，要么删。每一版都打磨到「再改就是把文气磨平、得不偿失」为止——到那一步才算到顶。下面六条，每次体检都要照着量：
1. **不许「说破情绪」。** 别直接告诉读者「很可怕／我很怕／这很瘆人／叫人发慌」，一律改成用画面、动作、身体反应、对照去「演」。（反例已删：「这种只有我一个人清醒的滋味，比那团气本身，还叫人发慌」。）
2. **套话成语,分两种对待,不搞一刀切。** 偷懒占位的空壳（张牙舞爪／千丝万缕／毛骨悚然这类,堆在那儿不干活的）——换成自己的、更具体的写法；直白常用语（一片空白／手忙脚乱这类,一眼就懂、正是最直接的说法）——用得其所就是好句,不因“常见”而废。判断标准只有一条：这个词在这儿,是不是干活最直接的那一个。
2-补. **不许为秀文采写别扭话（文采病）。** 描述的第一关是：正常人会不会这么说、读者是不是一眼就顺。声音就是“传来了／回来了／进了耳朵”，不是“扎回耳朵”。凡是叫读者停下来皱眉问“这词啥意思、为啥这么写”的“文采”，一律降级成大白话——大白话写得准，本身就是最好的文采。生动词可以用，但喻体必须贴着真实感受（玉烫得像烙铁摁在皮肉上＝贴；警笛声“扎”耳朵＝不贴、别扭）。为避重复而换词时，首选大白话平替，不许拿更冷、更怪的词充数（反例：嫌“撞回耳朵”重复，换成“扎回耳朵”——越换越怪，两头不是人）。

3. **少用虚词「东西／什么」。** 又虚又懒，堆多显廉价；能精确指代就精确（换「它」、换准确名词），只留有意的母题（如「那东西」）。
4. **开头别单调。** 别老用同一个字起头（「我…」「可…」「那…」）；换着开头，让长短句、节奏有起伏。
5. **递进句式别成口头禅。** 「越来越／越…越」「一…就」留最有力的一两处，其余换「渐渐／愈发／一点点／没完没了」或重写。
5-补. **物理反逻辑描述，铁律级禁止。** 凡写「X动了／X不动了／X停了」，先问一句：X 本来会动吗？胡茬是短硬的，不会动，也就无所谓「不动了」（长须被风吹才会动）；同理，方的不会滚、光照不进的地方别写「看清了物件」。写"全身静止"这类清单时，清单里的每一样都要单独过一遍物理关，不许为了排比顺手拉无辜的进来。

6-补. **「X个字」必对齐、每章至多一次；方言先核籍贯。** 凡写「说了X个字／这X个字」,先把引号里的中文汉字一个一个数清（只数汉字，标点、省略号一律不算）,差一个都不行;这一招每章至多用一次,连用就是口头禅,吃不准就写「他只说了一句」。方言词入嘴前先核人物籍贯:关中老汉嘴里不出川味、东北味的词,拿不准是不是当地话,就换大白话。

7. **分量反向闸（2026-07-17 作者令）。** 合规是底线，分量是骨肉：新章（第73章起）全章少于2000字＝硬错（2026-07-22 作者令：2500 旧线已拆、严禁为线凑字），除非施工表登记「第 N 章短章豁免」并写明理由（静水深流合法，但必须是选择，不是偷懒）；全书任何一章少于2000字、或全章没有一段≥120字的持续段、或均段长跌破30字，一律亮REVIEW。机器从此咬"薄"，和咬"错"一样狠——过闸最省事的路，不许再是"少写"。

6-补2. **反逻辑描述，零容忍。** 每个描写落笔前，在脑子里过一遍物理：这个部位、这件物件，现实里真做得出这个动作吗？胡茬是根，不会动（长须迎风才会动）；记忆里的话不走耳朵；方的物件不会滚；隔着灯罩，手够不着灯芯。凡是现实里摆不出来的画面，一律重写成摆得出来的。**新写的章，交稿前必须单独跑一遍「反逻辑」检查。**

6. **每一处都要「亮」。** 动词、形容词挑最准最有劲的；描写要具体、有画面、有新意；该瘆人的地方把那股劲焐足，不能只满足于「干净通顺」。

## ☆、九轮打磨 + 封神三问（每一章成稿前逐轮走查，冲击「中国第一」的完整体系）

> **凌驾一切的总纲——凡事不搞一刀切、不绝对化。**
> 文字的使用没有绝对标准。成语、俗语、套语、生理性恐惧描写——都能用，用得好都是升华。判断的唯一标准是三个字：**契合度**——它用在这个具体位置，是不是最贴切、最有力、最能传达出想传达的东西的那一个表达。
> - 用得好，成语套语也是文气的升华；生理性描写更是从侧面刻画人物心理的利器。
> - 只有当它「图省事、不够贴切、有更好的表达」时，才换。检查的是「度」和「契合度」，不是「是不是某一类词」。
> - **每一轮打磨，都先问「这儿最好的表达是什么」，而不是「这儿有没有某类词」。守卫、词单同受此约束，误伤了贴切的好词就精化守卫，坚决不一刀切。**
>
> **这套体系的正确定位——它是尺子，不是笔。** 它的职责是「守门」：保证这本书专业、干净、挑不出硬伤，并时时提醒往更高处够。但那个让人拍案叫绝、久久不忘的神来之笔，是「写」出来的，不是「查」出来的。伟大的小说核心是好故事、真实的人物、独一无二的声音、对人性的洞察——没有任何流程能替代创作。守住这把尺子是底线；真正的封神，靠往下写的每一个字。

**【九轮·防守——逐轮挑错，从宏观到微观，保证这一章挑不出硬伤】**

**第一轮·骨架关（逻辑与设定）**：逻辑闭环，每个因果都说得通，无硬伤（物理、时间线、光源、方位朝向）；设定不漂，世界观/人物/道具状态与前文一致；泄密红线一个字没松（照面章尤严：敌是谁、玉是什么、两千年历史，都不上纸）；巧合律、知识流律、四账（道具账/门户账/行程账/伏笔台账）全对得上；清初稿手误（破折号、英文词、错字）。

**第二轮·血肉关（该展开的展开）**：该演的高光演够了吗？最神奇、读者最想看清的那一下（玉合一、开眼、尸体呼吸、显形），给足慢镜头特写了吗？该展开的情节/心理，有没有图快被一句带过？关键的过程/转变，用递进细节一层层铺了吗？

**第三轮·人物关（人物弧光与情感真实）**：人物反应合乎人之常情吗？刚从生死线挣回来别云淡风轻，该有的后怕、紧张、火气得露出来。情感真实动人吗？读者记住的是人物不是情节，这一章有没有让人物「活」起来的一笔？人物做违背本能的事（怕却偏要看），写出内心的拉扯和驱动了吗？每个角色的「弧」有没有推进（她的立场、老头的暗线、苏衍的成长）？对白贴身份、贴情绪、轻重跟事态匹配吗？

**第四轮·字句关（用词最准·契合度优先不一刀切）**：关键动词/形容词是「最准」的还是「差不多能用」的？每个掐着挑最准的。成语/套语/生理描写——贴切就留，图省事才换（见总纲）。比喻自洽、贴切、一眼看懂有画面吗？抽象的「感觉句」写清楚没（主谓明确、有具体对照）？生理性恐惧描写只控制密度（别一章反复用同种、别跨章雷同），不禁用。

**第五轮·钩子关（开头接得住、结尾钩得狠）**：开头动静配得上上一章的钩子吗（别用小动静泄了大悬念的气）？开头别跟上一章结尾撞词撞句？章末必须停在揭露/危机/悬念上，收在「安稳」上的结尾重写？

**第六轮·冗余关（该删的删）**：同义反复删一个（整句/整段的语义重复，机器查不出、靠眼睛）？同一个鲜明的词/意象别在相邻句扎堆？上一章已演透的这一章别复述？**但——有意的修辞性重复（排比、层层递进、母题回响）要保留，这也是「不搞一刀切」。**

**第七轮·节奏关（张弛与呼吸）**：这一章的节奏对吗（大高潮后有没有喘息、铺垫够不够、张弛有没有度）？段落长短、句子长短有变化吗（一味长句或一味短句都累人）？该快的地方（动作、惊变）快得起来、该慢的地方（情感、悬念）沉得下去吗？有没有「闷」的段落——信息重复、推进停滞、读者会想跳过？

**第八轮·整体关（母题与呼应）**：密度对齐——这一章的完成度、字句密度，和全书最好的章一致吗？母题呼应——核心意象（玉温语法、活的墓、烧命护人）有没有照应？跨章——让开与前后章的撞词？

**第九轮·终审关（最苛刻的读者）**：以最苛刻读者的眼光从头到尾读一遍；所有改动处衔接顺不顺、有没有改出新问题（错字、断裂、前后不搭）？机检全项归零（四项零、禁名、台账、密度监控）？

**【封神三问·进攻——不是查错，是拔高，逼这一章长出让人忘不掉的东西】**

**一问·高光**：这一章，有没有一个能让读者记住、忘不掉、甚至想引用的「神来之笔」（一句话、一个意象、一个转折）？若没有，这章还只是「合格、干净」，没到「封神」——回去想，它的高光应该是什么。

**二问·全局**：跳出这一章，看它在整本书这盘棋里——位置对吗？推进主线了吗还是原地打转？信息节奏（几章一小揭、卷中反转、卷末大反转、埋钩与回收）踩在点上吗？

**三问·读者**：一个普通读者读到这儿，会不会想往下翻？哪一段他会走神、想跳过？哪一句他会心头一动？读完这一章，他有没有非追下一章不可的冲动？——这个拷问比任何技术检查都重要，读者手指一划就走了。

## 〇、故事圣经要点（设定不许漂）
- 唯一剧情权威：`设定/00_镇冢秘术_唯一总圣经.md`，CANON-ID=`ZM-CANON-20260722-101`。`canon事实库.json`只是机器镜像；写章与检索只允许再带入配套施工表，旧五项裁定、50轮闭环录、旧圣经、旧框架、旧“终极／唯一／定稿”文件与旧交接稿必须排除，均无裁决权。
- 主角苏衍：23岁，报社记者，由爷爷一人在关中塬上拉扯大；他从小就能看见“气”，不是合玉那晚才突然获得。
- 【时间线·不许写错】苏衍16岁离家进城，一去七年没回过。那半块玉是【七年前离家那天、在车站】爷爷红着眼眶、攥着他手塞给他的（说「发烫就回来」），他贴身焐了七年。爷爷是近日才去世，苏衍当年走后一直与爷爷疏远、【死时不在场】。所以：① 塞玉、爷爷的红眼眶只能写「当年/七年前/离别那回」，绝不能写「临死前/临终」；② 苏衍没见过爷爷「临死前」的样子，别让他描述死时的神情。
- 【年龄旧案·不许漂】沈鸢现年27岁，比苏衍大4岁；3岁时父母被霍钧杀害，距当前正好24年。霍钧此后抱走她、伪装救援并接管命令链。
- 地点与事件：出殡前守灵夜，苏衍在老宅地窖发现先祖古尸、从其手中取走另一半玉并合玉；老宅地窖绝非柏冢。柏冢的发掘、送葬、采访、入口与首次照面各服从正文首次完整原场。
- 柏冢入墓史只用B序：B1初入走官方方坑＋钢梯；B2首次重返走加固塌方斜口并原路出；B3二次重返仍走斜口进入，第36章钱满与沈鸢实际回探确认新木段四根梁断、塌土封顶且仍在下落，原路塌死，最终从隔山裂口出。不得让B3从斜口原路退出。E1—E8只编号八座外站；E1柏冢、E2楼兰已被动留下鼎心指纹，E3青溪起才有意识校准。
- B2地面拓扑：四人在洞内熄灭马灯，将灯与油囊装入工具袋，出斜口后仍在有遗留机器的封控内场。斜口最后半丈收在弃土垄北坡脚；土垄与北围挡间有一人伏卧夹槽，东南高哨看不见斜口和夹槽，只盯大半内场与土垄两端，因无人从两端露头而误判四人仍在地下。第17章西侧泄洪沟旧入口到第23章已被断朱砂线、新靴印和西边守卫封死；沈鸢白天预查北侧铁皮翘缝，因酸枣刺枝一动就会暴露，只能等第二夜按“装灯油的工具袋与其余器物先行、人俯卧送肩”的既定方案钻出。不得把斜口直接写成荒坡野洞，也不得让苏衍入夜临时发现出口。
- 柏冢诱捕与悬赏：黎线掌控项目、采访人选与原定晌午开封时段，只能预判认证宿主强开内层会触发本地防御回压，不能预知未来或精控塌方伤亡。排风设备审批和补签把实际开封拖到夜里，乡村配送批次未召回，悬赏才会在事故前到村。沈鸢以未登记身份混入，只负责让苏衍活着出来；启事只列苏衍。
- 人间证据链：第13章苏衍已经联系派出所老同学；被卡住的是嵌入基金会协办员的当地移交链，不是所有警察。先保悬赏原件、做副本，再交外地记者、律师和互不隶属办案机关多点留底。塌方后公安／文保／应急外围封控常驻，黎线只以专业排险为名清空内场；第17章主角绕岗进入，不能写全场蒸发。六名民工先登记安全撤场，后在统一转运中失踪但全部存活：四人被强制转运、两人遭非法拘禁。
- 血图与随身证物：血图原件、玄微尸腕、原始衣裹层源印联锁；第13章必须试取并确认硬抽会毁印，卷六用公输卸力法和刚性运尸匣整体转运。手机里有第一层柏冢细图和第二层九点／淡线／粗轮廓，暗金气路拍不进去。第60章起，关机诺基亚＋事故前悬赏原件＋红绳旧铜钥匙贴身随队。楼兰沙海靠罗盘、北斗、本脉旧账和固定地标，玉绝不导航。
- 时间与揭晓：第28章广播只用“今年以来／近期”，严禁“入夏以来”、未来季节广播或时间回声。楼兰后隐蔽南下三个多月；青溪首响账证在农历二月页，队伍于农历五月二十六夜抵寨，二十七日清晨核证。第40章墓内黎明，北京幕间须明确“同日傍晚”；第57章第二晚电视首次报黎东来并收章，第58章第三日清早沈鸢再自报姓名、解释旧档，禁倒拨时辰补首播。
- 玉的现行语义：合玉以后是完整古玉；只响应高浓度同源能量、载体或封印，可同时响应多个同源源头；不侦测普通敌意，不判断安全，不规划路线。地图给目的地，路线由人决定。
- 代价两账必须分开：强接鼎心联结产生的每一道白光是当场结算的一次性大账；频繁／重度望气是逐渐烧损承载力的慢耗。合玉只出现一次青润认证光。青溪黑影是不能离开本地气路、不会等待或谋划的无人格接口；白光只冲散单次投影。
- 人物决定与青溪预警：苏衍必须追问沈鸢的旧档、师父和识路异常；南下与进雾岭由他综合证据后亲口决定，老头不替全队承诺。第66章以灰黑细流收束、牲畜避坡、山响回憋完成预警；第68章只推进叫魂；第69章由积水灌入黑口、坡脚裂响触发暴雨塌坡，露出导流层并释放探针。
- 终局生命三层：霍钧只是在尚未断气时沿同源旧伤接续命线，从未复活；沈鸢完整活气断绝后不能新接或救活。赵阙会拿霍钧作伪证诱骗苏衍先交总流；苏衍留流也只能保尸，不能恢复意识与人生。老头击落臂刀时必须喊“割绳”，本意是脱身参战，绝非设计自尽。
- 总圣经核心禁则：黎东来清醒自愿作恶，不附身、不夺舍；赵阙不能接管苏衍身体；苏玄微不是原邪阵共谋；爷爷不是机械锁芯。古尸不与爷爷同脸、同痣或同鼻疤；钱满不是公输血脉、旁支或传人。天下本有自然循环；终局为赵阙台、苏衍台、玄微台三台；地窖合玉仅低功率认证，骊山入台才启动主回路。
- 维护伏笔台账：留的谜要记着、要回收，最终拢成一个完美闭环。

## 一、物理逻辑（最容易翻车，逐条死守）
1. 诺基亚7610 / 小手电筒 / 光，三样分清。
   - 诺基亚7610＝方形实物：会摔、会掉、会攥、会捡；没有现代手机的背面手电，也不是针顶卡托结构。
   - 小手电筒＝独立的圆柱实物：会滚、会脱手、会摔；第1章权威原场就是苏衍携带的小手电筒。
   - 那束光 / 光柱 / 光圈＝光本身：只能照、能晃。
   - 光源前后必须对得上：小手电筒亮着且未被遮住，就不能写“一片漆黑”；要写摸黑，先交代熄灭、滚远、被压住或遮挡。7610只能用屏幕微光，不能补写不存在的后置灯。
   - 「气」不是光：望气只看得见气/光脉，气本身照不亮实物。所以漆黑里他看得见气，却看不清地上的手机、棺、人；要看清这些「物」，仍得靠真实的光（手电筒、油灯、烛火）。
2. 方的东西不会滚（手机、砖头之类）。凡写「摔、掉、滚、滑、亮、灭」，落笔前先在脑子里走一遍它实际会怎么动。
3. 比喻要自洽，更要贴切、有联系：
   - ① 自洽：喻体本身得真能干出后面那个动作。钝刀做不出利落一刀，要利落就用「快刀/利刃」。
   - ② 贴切、有联系：喻体必须跟本体真有关联、贴得上、够生动，不能为「文学」硬凑一个八竿子打不着的。
   - 反面铁证：人只是「看不见东西、被气团团围住」，却比作「泡进一锅煮沸的水里」——水、煮沸跟「看见气」毫无关系，还平白带出烫伤、淹死的歧义。纯属乱比喻，删。
   - 打比方前先问一句：这个喻体，真能让读者更准地体会到本体那个样子/感觉吗？不能，就别比，直接把那个样子写出来。

## 二、人物「能不能知道」
4. 不让人物断他根本断不了的事；凡是拿不准的，一律别写死。
   - 通则：从头到尾，只要是人物没法完全确定的事，就别用斩钉截铁的口气写，要留余地（「不知多少年」「像是」「怕是」「说不清」）。作者自己都拿不准，却写得笃定无比，就是不严谨。
   - 典型坑——尸体年头：保存太好太新→根本看不出年头；「两千多年」只能从朽成灰的秦代衣裳上推，而且要写「不知多少个年头」。不许写死「一具躺了两千多年的死尸」，也别在比喻里冒出「停跳了两千年的心脏」这种精确数字（改「不知多少年」）。
   - 前后还要一致：一处已经写「不知多少个年头」，别另一处又突然「两千多年」，自打嘴巴。
5. 人物的「知道」都要有来源。老头能说尸体手里攥着那地方的地图，是因为苏衍当场指给他、告诉了他。故意留的「超常之知」（如老头怎知苏衍合了玉），要让当事人当场点破「这不可能」，标明是谜、不是穿帮。
5b. 人物的判断也要合逻辑、前后自洽。由观察推出来的结论（听老头喊尸体「老哥」、说爷爷守了一辈子，就猜出他认得爷爷）是合情合理的，绝不能反手说它「荒唐至极」「荒谬」——那是自相矛盾。形容词、程度词也别跟摆出的事实打架：说人「七八十岁」，就别又说他「极老极老」（那得九十上百）；叠词（极X极X）别灌水，老相用具体描写去撑。

## 三、跨章一致
6. 尸体的眼睛全程是「睁着」的（第一章定的，是最初那记惊吓的核心）。后文别写成闭着/睁开眼。它要吓人，是那双睁着的死眼会不会突然转过来、落到他身上。
7. 称呼前后一致，且跟情绪走：苏衍对老头一律「你」，对爷爷也用「你」。情绪顶点（吼、崩溃）绝不用敬称「您」——礼数是情绪一上头最先垮的东西。
   - 提及爷爷过世，措辞放敬些：平静、追忆处用「去世、走了」，不用直白的「爷爷死了」。但崩溃喊叫里「死了」那股生硬反倒更见痛，照旧；恐怖场景里的「死人/死尸」也照旧。

## 四、标点 & 行文节奏
8. 对话引号用全角「" "」，不用英文直引号。
9. 破折号只用单独一道「—」，不用「——」（两道），而且要少之又少。很多地方根本不用破折号：话说完用句号；话没说完、拖音、欲言又止用省略号「……」；并列、停顿用逗号。破折号只留给真正的「猛然打断／插进来一句」。破折号一多，就显得乱、招人烦。
10. 逗号别用得太密、别把句子顿得太碎。能一句话顺下来的，就别拿逗号切成一节一节。长短句搭配，该顺则顺，该断才断。
11. 独占一行的极短句别滥用，只在真正的节点上用；口头禅（如「原来不是」「果然」）别反复。

## 五、写法总纲
12. 慢，有人味：任何恐惧/震惊/悲痛/抉择，先写人最原始的本能反应（尖叫、后缩、脑子空白、干呕、发抖），再写理性的观察。别让叙述者平静地把可怕的事当既成事实陈述。
   - 别为文气掉书袋：平常话能说清的就用大白话，别堆生硬术语或雅词（如「夯土的窖壁」「冰冷的窖底」「旮旯」「翕动」）。尤其人物正发懵、崩溃时，脑子里不会蹦专业词，用词得贴着那一刻的心境。
   - 描述要让人一读就懂，别别扭绕口、别过度细节、别用错量词（反面：「台阶早出了我这点光的边」→「手电光照不到台阶顶上」；「拦在那地方的千里之外」→「不让你离那地方近半步」；「憋着一包眼泪」→「泪水在眼眶里直打转」；「窖壁」→「墙」）。
   - 对白要贴身份、接地气。在村里活了几十年的老头，不会拽「不宜久待」这种书面文话，该说「待久了对你没好处」。文绉绉的词（莫要、切莫、速速、岂能、何故……）尤其别往人物嘴里塞。
13. 藏谜底：「发生了什么」（动作、感官、反应）写得清清楚楚；「这一切意味着什么」（谜底、来历、真相）一个字别松——那些谜正是拽读者往下看的钩子。
14. 恐惧意象每次不重样：轮换头皮、汗毛、鸡皮疙瘩、寒意、心跳、腿软、胃翻、血凉……同一种身体反应别连用。用词别重复。
15. 每章一个强钩子，章末留扣。

## 六、道具的讲究
16. 油灯不是随手写的照明，是「报信」的家伙：火苗会随阴气/煞气而变（狂跳、骤缩、发暗、变色），所以这一行的人靠它示警、不用手电筒（死光，什么都不告诉你）。地窖里「灯影一晃一晃」未必全是风——它一直在报信，只是苏衍还是外行，看不懂。

## 七、交付
17. 每章独立 .md；全角引号；写完呈给用户。
18. 任何输出都不准出现老师称谓或人名（标准长期偏好）。
"""

