#    中文没分词,2字窗会切出碎词,所以①排除"一/数字/这那什/极"开头②排除虚词③排除一串必然重现的
#    话题词④窗口收得很近⑤每章最多列几条。定位是"提个醒(FYI)",不算硬伤——多为正常母题,只挑无意扎堆的删。
