# ═══════════════════════════════════════════════════════════════
#   超级智能体 v5.3 —— 小说检察官当前入口
#   外部 canon 为强制权威；内嵌仅保留早期通用机械规则且不能脱库运行；
#   第一优先级=canon保真与回述保真;
#   回述/绝对化自动跨章对撞;欠写雷达;双重保障第二道闸(AI核查令)。
#   入口: 无参=全书 | N=封版门 | *.md=封版门 | --末章 N | --十一轮 N | --doctor | --selftest（一代诸令 1027 汰）
# ═══════════════════════════════════════════════════════════════
import json as _json, os as _os
_EMBEDDED_LIB=_json.loads(r'''{"_说明": "canon事实库:每立一条新canon必须同步追加。level=ERROR(封版前必须清零)/FYI(债务仪表)。except_ch=豁免章号。", "facts": [{"id": "F001_暗门机关", "note": "堂屋暗门=补丁皮下铜钥匙锁孔(ch1权威);爷爷从未教授开门法", "level": "ERROR", "forbid": ["爷爷[^。，\n]{0,8}教过我", "和爷爷教我的", "爷爷临走前教", "哪一块砖该按", "没有把手，没有锁孔", "老宅[^。\n]{0,25}没有锁孔"], "except_ch": []}, {"id": "F002_年龄", "note": "苏衍=23岁;禁任何'我+二十X(≠三)'", "level": "ERROR", "forbid": ["我[^。\n]{0,4}二十[一二四五六七八九]"], "except_ch": []}, {"id": "F003_玉交接", "note": "ch1权威:红布包塞手;禁'戴到我的脖子'", "level": "ERROR", "forbid": ["戴到了?我的脖"], "except_ch": []}, {"id": "F004_浅纹初见", "note": "初见=ch22马灯下;禁他章自称头一回见纹", "level": "ERROR", "forbid": ["头一回[^。\n]{0,12}[瞧看]见[^。\n]{0,10}纹", "[瞧看]见[^。\n]{0,6}纹[^。\n]{0,8}头一回"], "except_ch": [22]}, {"id": "F005_手机手电", "note": "7610无手电;照明=手电筒/屏;禁'手机…的手电/背面的手电'及'从未见过它发光'", "level": "ERROR", "forbid": ["手机[^。\n]{0,10}的手电", "背面的手电", "从未见过它发光"], "except_ch": []}, {"id": "F006_年份", "note": "全书=2006;禁一切错年份", "level": "ERROR", "forbid": ["二〇〇[一二三四五七八九]年", "二〇一.?年", "一九九[〇0-9]", "19[89][0-9]年", "200[0-57-9]年"], "except_ch": []}, {"id": "F007_打介词", "note": "打作方位/时间介词全书禁(含对白)", "level": "ERROR", "forbid": ["打[这那北南东西明今后小心进出]"], "except_ch": []}, {"id": "F008_禀报转折", "note": "禀报式转折禁(变故陡生类)", "level": "ERROR", "forbid": ["变故陡生", "变故突生", "意外就在这时", "说时迟"], "except_ch": []}, {"id": "F010_债词仪表", "note": "债词:新章回避;旧章计数观察", "level": "FYI", "forbid": ["一寸一寸", "纹丝不动", "后脊梁", "就在这时", "喉咙发紧", "一下，一下", "九死一生", "亘古"], "except_ch": []}], "musts": [{"ch": 12, "pat": "二〇〇六年二月十七日", "note": "悬赏落款年份主锚"}, {"ch": 9, "pat": "诺基亚7610", "note": "机型唯一点名处"}, {"ch": 9, "pat": "一百万像素", "note": "像素话术"}, {"ch": 22, "pat": "我今年二十三", "note": "年龄修复钉"}, {"ch": 20, "pat": "一个字都没教过", "note": "静地案修复钉"}, {"ch": 1, "pat": "小手电筒", "note": "守灵手电canon"}, {"ch": 1, "pat": "锈铁钉", "note": "空钉子伏笔"}, {"ch": 17, "pat": "红彤彤的二〇〇六", "note": "挂历辅锚"}, {"ch": 60, "pat": "整整一个楼兰", "note": "浅纹链终锚"}], "reveal": {"黎东来": 57, "柏冢": 13, "钱满": 18}, "perm_forbidden": ["望气", "鼎心", "换锚", "抽气运", "九处", "验钥台", "大阵", "阵眼", "锚位", "点亮", "气运", "夺舍", "龙脉", "鼎使", "守鼎", "第九鼎", "九鼎", "赵阙", "苏玄微", "樗里", "青乌", "执刑", "沈鸢", "殉葬"], "mech5_except": ["我怕脚下的某一块青砖", "从这座厅堂的最深处", "往那道透着晨光的缝隙", "是埋在土底下的那桩", "背后跟着两个把命交给我的人"], "abs_ok": ["这样的东西，我从没见过", "从没见过它像此刻这样", "从未闻过的东西", "我从没见过那样的地方", "从未走过这样漫长"]}''')
# ★1027·执行之审 #13 之守（线 D）：D1（老头之年·四十八年前；圣经 改单#G0929-01、裁_1020_D1落式）落後，
#   白文「二十七年」之年数语境回退即红（D1施 之六式「「二十七年」作年义」残 0 之常守；⛔只验一回）。
#   ★其开关：瑕疵总账 X17 之行在「## 未治」节＝D1 未落（207 处係已挂之账，由账限哨催，此守只记 FYI ⛔拦）；
#     X17 移出未治（线 E 器施 D1 後移已治）即开——此後白文再见一处即 ERROR（全书检、--末章 俱拦）。
#   ⛔误拦之防：只跑白文（亮点层只印 ℹ）；「一百二十七年」之类前带数字者⛔中。
_D1守之式 = r'(?<![〇零一二三四五六七八九十百千两])二十七年'


def _D1已落(账文=None):
    """D1 落否：瑕疵总账「## 未治」节无 X17 之行 → 已落。账读不得 → 作已落（宁严：守照拦）。"""
    if 账文 is None:
        try:
            账文 = open(os.path.join(REPO_ROOT, '设定', '瑕疵总账.md'), encoding='utf-8').read()
        except OSError:
            return True
    m = re.search(r'(?ms)^## 未治[^\n]*\n(.*?)(?=^## |\Z)', 账文)
    return not (m and re.search(r'(?m)^\|\s*X17\s*\|', m.group(1)))


def _D1守(落):
    return {'id': 'D1守_老头之年', 'level': 'ERROR' if 落 else 'FYI',
            'note': '老头之年：四十八年前（D1·圣经 改单#G0929-01）；白文⛔「二十七年」（D1 落後之常守·执行之审 #13）',
            'forbid': [_D1守之式], 'except_ch': []}


def _load_lib():
    lib=_json.loads(_json.dumps(_EMBEDDED_LIB))
    p=CANON_PATH
    if _os.path.exists(p):
        try:
            ext=_json.load(open(p,encoding='utf-8'))
        except (OSError, ValueError) as exc:
            raise SystemExit(f'  ✗ canon事实库无法读取: {p}\n    {exc}')
        authority=ext.get('authority',{})
        if authority.get('canon_id') != EXPECTED_CANON_ID:
            raise SystemExit('  ✗ canon事实库 CANON-ID 不匹配；拒绝使用过期镜像')
        if authority.get('master') != EXPECTED_MASTER_REL:
            raise SystemExit('  ✗ canon事实库未指向唯一总圣经；体检已中止')
        if authority.get('order') != EXPECTED_AUTHORITY_ORDER:
            raise SystemExit('  ✗ canon权威序必须为：唯一总圣经→JSON镜像→未被推翻的首个完整原场')
        if authority.get('active_inputs') != EXPECTED_ACTIVE_INPUTS:
            raise SystemExit('  ✗ canon活动输入必须且只能是：唯一总圣经＋配套施工表＋事实库；旧设定不得混入')
        if not _os.path.isfile(MASTER_CANON_PATH):
            raise SystemExit(f'  ✗ 唯一总圣经缺失: {MASTER_CANON_PATH}')
        try:
            master_text=open(MASTER_CANON_PATH,encoding='utf-8').read()
        except OSError as exc:
            raise SystemExit(f'  ✗ 唯一总圣经无法读取: {exc}')
        if EXPECTED_CANON_ID not in master_text:
            raise SystemExit('  ✗ 唯一总圣经不含期望 CANON-ID；体检已中止')
        ids={f['id']:i for i,f in enumerate(lib['facts'])}
        for f in ext.get('facts',[]):
            if f['id'] in ids: lib['facts'][ids[f['id']]]=f
            else: lib['facts'].append(f)
        seen={(m['ch'],m['pat']) for m in lib['musts']}
        lib['musts']+= [m for m in ext.get('musts',[]) if (m['ch'],m['pat']) not in seen]
        lib['reveal'].update(ext.get('reveal',{}))
        # 外部 canon 是强制镜像；不与内嵌旧红线取并集，否则旧“沈鸢永禁”会压过第58章揭名新 canon。
        lib['perm_forbidden']=list(ext.get('perm_forbidden',lib['perm_forbidden']))
        for k in ('abs_ok','foreshadows','state_canon','timeline','roster','concept_canon'):
            if k in ext: lib[k]=ext[k]
        lib['mech5_except']=sorted(set(lib.get('mech5_except',[]))|set(ext.get('mech5_except',[])))
        lib['abs_ok']=sorted(set(lib.get('abs_ok',[]))|set(ext.get('abs_ok',[])))
    else:
        raise SystemExit(f'  ✗ 项目 canon 缺失: {p}\n    为防止使用过期内嵌库产生假全绿，体检已中止。')
    if not any(f.get('id') == 'D1守_老头之年' for f in lib['facts']):
        lib['facts'].append(_D1守(_D1已落()))
    return lib
def _chapters():
    fs={}
    for f in glob.glob(_os.path.join(CHAPTER_DIR, '镇冢秘术_第*章_*.md')):
        m=re.search(r'第(.+?)章_(.+?)\.md',f)
        n=_chap_num(f)
        if m and n != 9999: fs[n]=(f,m.group(2),open(f,encoding='utf-8').read())
    return fs

def _scope(files, focus=None):
    return [focus] if focus is not None else sorted(files)

def _chapter_gaps(files):
    if not files:
        return []
    return [n for n in range(1, max(files)+1) if n not in files]

def _whole_jade_violations(text):
    """拦合玉后的当前/无锚“半块玉”；明确历史回忆放行。"""
    hits=[]
    historical=('七年前','当年','当时','离家','车站','一场大雪后','爷爷为什么','爷爷去世','爷爷死','爷爷走','爷爷塞','爷爷把','爷爷给','爷爷交','塞给我','交给我','那时','小时候','想起','回想','曾经','原先')
    now=('此刻','这会儿','如今','眼下','现在','仍在','还在','又开始','我从怀里','我从胸口','我低头')
    for m in re.finditer(r'半[块枚]玉', text):
        lo=max(0, text.rfind('。',0,m.start())+1)
        hi=text.find('。',m.end())
        if hi<0: hi=min(len(text),m.end()+50)
        sent=text[lo:hi+1]
        if any(k in sent for k in historical) and not any(k in sent for k in now):
            continue
        hits.append((m.start(),sent.strip()))
    return hits
def _ln(t,pos): return t.count('\n',0,pos)+1
def _bodyx(t):
    t=t.split('【本章亮点】')[0]
    return re.sub(r'^.*?第.+?章[^\n]*\n','',t,count=1,flags=re.S)

def priority_one(files,focus,lib):
    ERR=0
    tg=_scope(files,focus)
    tg=[n for n in tg if n in files]
    print('█【第一优先级 · canon保真】伪造记忆/事实违背——出现一次全书即毁,首查')
    e0=ERR
    for fa in lib['facts']:
        if fa.get('level')!='ERROR': continue
        exc=set(fa.get('except_ch',[]))
        only=set(fa.get('only_ch',[]))
        for n in tg:
            if n in exc or n < fa.get('from_ch',1) or (only and n not in only): continue
            t=files[n][2]
            # ★★★★★2026-09-18·346 之实（`裁_0918_硬条346其一…` 同日之第二件）：
            #   ⛔**旧式把 forbid 正则跑在整个档上——而档里有两层**：
            #     **白文（读者读的那一层）＋【本章亮点】之後的骨记（本席自己的工作记录）。**
            #   ★**其红之实样**（346 行168）：骨记那一节正在**自证它守住了 F034**，
            #     其文引圣经 2468「只有公输后人认得」，隔一句又引 692「不给钱满…」——
            #     ⛔**两句引文之间跨了一个句号，而 F034 之第三式 `(公输|鲁班)…(后人)…钱满`
            #        的字符窗正好把两段引文缝在一处**。
            #   ★★**即：一个章因为写下「本章没有犯这一条」而被判犯了这一条。**
            #     ⛔**这样的闸不是严，是量错了地方**——**读者一辈子读不到骨记一个字。**
            #   ★★★**故今只改其量之界：forbid 只跑白文。**
            #     ⛔**而骨记那一层不许静悄悄放过**：其命中当场印出来，作 `ℹ` 一格（⛔不计 ERROR），
            #     **使「骨记里引了禁式」这件事日後仍看得见，只是不再拿它挡封版。**
            _bai = t.split('【本章亮点】')[0]
            _liang = t[len(_bai):]
            for p in fa['forbid']:
                for m in re.finditer(p,_bai):
                    ERR+=1; print(f'  ✗第{n}章 [{fa["id"]}]行{_ln(_bai,m.start())}: …{_bai[max(0,m.start()-14):m.end()+22]}…'.replace(chr(10),'␤'))
                for m in re.finditer(p,_liang):
                    print(f'  ℹ第{n}章 [{fa["id"]}]亮点层命中（⛔不计ERROR·读者读不到这一层）: …{_liang[max(0,m.start()-14):m.end()+22]}…'.replace(chr(10),'␤'))
            if fa.get('checker')=='whole_jade_after_merge':
                for pos,sent in _whole_jade_violations(t):
                    ERR+=1
                    print(f'  ✗第{n}章 [{fa["id"]}]行{_ln(t,pos)}: 当前实物已合一，不得退回“半块玉” …{sent[:52]}…')
    for mr in lib['musts']:
        if focus and mr['ch']!=focus: continue
        if mr['ch'] not in files: continue
        try:
            present=(re.search(mr['pat'],files[mr['ch']][2]) is not None) if mr.get('regex') else (mr['pat'] in files[mr['ch']][2])
        except re.error as exc:
            raise SystemExit(f'  ✗ canon事实库回归钉正则无效: ch{mr["ch"]} / {mr["pat"]}\n    {exc}')
        if not present:
            ERR+=1
            kind='正则' if mr.get('regex') else '原句'
            print(f'  ✗第{mr["ch"]}章 回归钉缺失[{kind}:{mr["pat"]}]')
    if ERR==e0: print('  ✓ 事实层零违背,回归钉全在位')
    # 回述自动对撞
    print('█【第一优先级 · 回述保真】回述句自动跨章对撞(AI须贴原场逐字比对):')
    cnt=0
    for n in tg:
        t=_bodyx(files[n][2])
        for s in re.split(r'(?<=[。！？…])',t):
            if any(k in s for k in ['想起','我记得','当日','那晚在','那一夜，','爷爷临走','爷爷生前','那时候他','翻了上来','记起','当年','那一回','那天在','从小听到','上一回','小时候的']) and len(s)>14:
                kws=[w for w in re.findall(r'[\u4e00-\u9fff]{2,4}',s) if w not in ('想起','记得','那晚','当日','一夜','时候','我们','什么','没有','这个','那个','一个','自己','已经','这样','那样')][:3]
                src=[]
                for m2 in sorted(files):
                    if m2>=n: break
                    for kw in kws:
                        if kw in files[m2][2]: src.append(f'{kw}→第{m2}章'); break
                cnt+=1
                if focus or src:
                    print(f'  ?第{n}章:',s.strip()[:44]+'…','｜原场线索:',('；'.join(src[:3]) or '前文未见(若为跨章回述=红灯)'))
                if not focus and cnt>=14: break
        if not focus and cnt>=14: break
    if cnt==0: print('  (本范围无回述句)')
    return ERR

def abs_collide(files,focus,lib):
    print('█【绝对化自动对撞】"第一次/从没见过X"——机器先去前文搜X:')
    tg=_scope(files,focus)
    ok=lib.get('abs_ok',[]); shown=0
    for n in tg:
        if n not in files: continue
        t=_bodyx(files[n][2])
        for m in re.finditer(r'(第一次|头一回|头一遭|从没|从未)(?:见过|听过|有过|闻过|经历过|看清|瞧见)?([^。，"”]{2,10})',t):
            whole=m.group(0)
            if any(o in whole or whole in o for o in ok): continue
            obj=re.sub(r'^(这样|那样|如此|的|地|它|他|她)+','',m.group(2))[:4]
            if len(obj)<2: continue
            hits=[m2 for m2 in sorted(files) if m2<n and obj in files[m2][2]]
            if hits:
                shown+=1
                print(f'  ⚠第{n}章「{whole[:16]}」← "{obj}"已见于第{hits[:3]}章 → AI裁定(违背则修/属实则登记abs_ok)')
                if not focus and shown>=12: print('  …(全书模式仅展示前12条,单章模式全量)'); return
    if shown==0: print('  ✓ 无未登记的疑似违背')

def underwrite_radar(files,focus):
    print('█【欠写雷达】高潮词落在超短段=疑似"省字/一笔带过"(AI裁定):')
    KW=['合一','合成了','睁开了眼','睁眼','现出','现身','炸开','塌了下来','扑了过来','断了','亮了起来','出现在','头一回','终于','推开了']
    tg=_scope(files,focus)
    tot=sum(len(re.findall(r'[\u4e00-\u9fff]',files[n][2])) for n in tg if n in files)
    avg=tot//max(1,len(tg)); shown=0
    for n in tg:
        if n not in files: continue
        t=_bodyx(files[n][2])
        cs=len(re.findall(r'[\u4e00-\u9fff]',t))
        if not focus and cs<avg*0.62: print(f'  ⚠第{n}章仅{cs}字(均值{avg}) → 核查是否有戏被压薄')
        for p in [x.strip() for x in re.split(r'\n\s*\n',t) if x.strip()]:
            if len(p)<34 and any(k in p for k in KW) and '"' not in p and '“' not in p:
                shown+=1; print(f'  ?第{n}章 短段含高潮词: {p[:30]}…' if len(p)>30 else f'  ?第{n}章 短段含高潮词: {p}')
                if not focus and shown>=10: return
    if shown==0: print('  ✓ 未见高潮词短段(短句蓄力型除外,由AI终裁)')

# ★单字爷之许（判法一字未动，只把许词抽出来以便负测）：其禁所守者「称呼爷爷须叫全两个字」（本档 3844／3848／3992）。
# ★2026-10-08·380 案席补「禹王爷」：老头土话「禹王爷铸的那九个物件」係圣经:959、:1161、:2697 与总纲:826 所立之句，
#   与「阎王爷」同属神号，不是单叫一个爷字；全测之全书检因之报 380:67、380:132 两处 ERROR，係许词表漏收，不是文错。
#   ⛔只收「禹王爷」三字整词，不收「王爷」——单说「王爷」照旧红（负测见 selftest 之 ye_checks）。
_爷许 = ('爷爷','老爷子','阎王爷','禹王爷','爷俩','爷孙','爷们','大爷','太爷','天爷')
# ★2026-10-21·402 记席补整词之许：罗之句「我爷的回字牌，出门押在外头，回来取。」係余章总案:67 所立原字，
#   状态册门里那个人之身份注「402『我爷』分之」（与 110 姓罗者、与苏衍之「爷爷」分开）——是他称自家先人，不是苏衍单叫一个爷字。
#   ⛔只收此一整词（逐字整串比对，不入两字窗）：单叫「爷」、他句之「我爷的」照旧红（负测见 selftest 之 ye_checks）。
_爷整词许 = ('我爷的回字牌',)
def _单字爷(t):
    out=[]
    for m in re.finditer('爷',t):
        a=t[max(0,m.start()-2):m.end()+2]
        if any(w in a for w in _爷许): continue
        if any(t.startswith(w, m.start()-w.index('爷')) for w in _爷整词许 if m.start()-w.index('爷')>=0): continue
        out.append(m.start())
    return out

def mech_layer(files,focus,lib):
    ERR=0; M5X=lib.get('mech5_except',[])
    tg=_scope(files,focus)
    print('█【机械铁律】破折/半角/英文/5+逗/单字爷 █【红线揭名】')
    for n in tg:
        if n not in files: continue
        f,nm,t=files[n]; pr=[]
        if '——' in t: pr.append(f'破折号×{t.count("——")}')
        for m in re.finditer(r'[,\?!;:]',t): pr.append(f'半角"{m.group()}"行{_ln(t,m.start())}')
        # ★★★★★2026-09-01 治·此闸自立起之日即不存在（全书审计所逮）：
        #   ★r-string 里的 `\\1` 是「反斜杠＋1」两个字面字符，不是反向引用；
        #   ★★实测 re.findall(r'(那个)\\1','那个那个记号') → []，而 r'(那个)\1' → ['那个']
        #   ★★★故这道闸从第一天起一次也没红过，而它红不红没人查过。
        # ★而同日另治一处：其词表含「一个」，改对之後全书命中 34 处，
        #   ★★三十四处尽是「一个一个」（他把五个罐子一个一个提起来／一个一个点过去），
        #   ★★★那是好话不是粘连 ⛔ → 去「一个」，去後全书命中 0 处（今日回灌所验）。
        for m in re.finditer(r'(那包|那个|那块|那道|那把|那面|这个|这块)\1',t): pr.append(f'叠词粘连"{m.group()}"行{_ln(t,m.start())}')
        for m in re.finditer(r'[A-Za-z]+',t): pr.append(f'英文"{m.group()}"行{_ln(t,m.start())}')
        for s in re.split(r'(?<=[。！？…])',t):
            if s.count('，')>=5 and not any(x in s for x in M5X): pr.append('5+逗:'+s.strip()[:24]+'…')
        # ★★★★★第十九条机械铁律（第193章第10轮所立）：一句之内二冒号
        # ★其由：本书之破折已全改为冒号（——→：），而原本已有冒号之句，改完即成二冒号
        # ★★而一句两冒号，读来无从分其主从——前一个说的是「下头要摆什么」，后一个又说一遍，其势即塌
        # ★★★而其只对第200章及以后之新章报硬项；
        # ★★★★已封版之24章36处为存量，依「封版之后不再动」之律，另记冷轮_COLD193_二冒号全书账.md
        # ★★★★★而其只扫正文，不扫亮点段——亮点段以冒号引句为体例，非病
        if n >= 200:
            for s in re.split(r'(?<=[。！？…])',t.split('【本章亮点')[0]):
                if s.count('：')>=2: pr.append('二冒号:'+s.strip()[:24]+'…')
        # ★★★★★第二十条机械铁律（第291章第12轮·极限轮所立）：数句闸
        # ★其由：291断言「他今天说了六句」，而正文里数得出来的是「他说」十一处；
        #   ★★而第3轮·逐数对表判其过——其判据是「此数有没有对头」，不是「此数自己对不对」；
        #   ★★★於是一个数与另一个数比着，两边都没被数过，这一格年年绿。
        # ★★★★其群（立闸之日所数）：本书正文里「时点＋说/答/问 + 四五六七八九十句」共十处；
        #   其九处皆在页上给了明细（「九句里头，三句是令：」「四句：第七十九天问…」）或逐句编号（第一句…第五句），
        #   ★唯291一处既无明细亦无编号 → 今补明细，全书报红归零（负测_数句闸.py 以改前之291回灌，须报红2处）。
        # ★★★★★而它认不着的（立闸之日须写明，不许把它的绿读成「凡数皆可数」）：
        #   ①单独成拍之数（第134章「九句。」、第138章「七句。」）——其前无说/答之动词，此闸不认；
        #   ②跨章累计（第179章「统共说过四句话」、第183章「统共说过八句」）——须与前章递数，另立他闸，今日未立；
        #   ③「N个字」之数（三个字／两个字）——那一类可当场数字，本闸不管。
        _SJ_TIME = r'今天|昨天|前天|第[一二三四五六七八九十百零]+天|这一回|那一回|这一路|到这会儿|这五天|这三天'
        for m in re.finditer(r'([四五六七八九十])句', t.split('【本章亮点')[0]):
            _q = m.group(1); _pre = t[max(0,m.start()-28):m.start()]
            if not re.search(_SJ_TIME,_pre): continue
            if not re.search(r'说|答|问|报|开口',_pre): continue
            if re.search(r'统共|加起来|一共', t[max(0,m.start()-28):m.end()+60]): continue
            _w = t[max(0,m.start()-400):m.end()+400]
            if re.search(_q+r'句.{0,15}[：:]',_w): continue
            if re.search(_q+r'句(里头|里|，句句)',_w): continue
            if len(re.findall(r'第[一二三四五六七八九十]句',_w))>=2: continue
            pr.append(f'数句无明细[{_q}句]行{_ln(t,m.start())}')
        for _p in _单字爷(t): pr.append(f'单字爷 行{_ln(t,_p)}')
        for w in lib['perm_forbidden']:
            for m in re.finditer(re.escape(w),t): pr.append(f'永禁[{w}]行{_ln(t,m.start())}')
        for w,rv in lib['reveal'].items():
            if (rv is None or n<rv) and w in t: pr.append(f'未到揭名[{w}≥{rv}]')
        wc,_,_=_weight_stats(t)
        if wc>MAX_CHARS_SOFT:
            print(f'  ▲第{n}章体量提醒:全章{wc}字>10000,可自查是否分章(不判错)')
        if n==max(files):
            _facts_blob=json.dumps(lib['facts'],ensure_ascii=False) if 'json' in dir() else str(lib['facts'])
            _cand=sorted(set(m.group() for m in re.finditer(r'[一二三四五六七八九十百千两]{1,5}(?:步|息|盏|声|岁|丈|里|年)',_bodyx(t))))
            _new=[x for x in _cand if x not in _facts_blob][:12]
            _bt=_bodyx(t)
            _stop=('老头','钱满','沈鸢','苏衍','我们','他们','的时候','一个字','没有人','这一回')
            _gr={}
            for _i in range(len(_bt)-3):
                _g=_bt[_i:_i+4]
                if re.fullmatch(r'[\u4e00-\u9fff]{4}',_g) and _g not in _stop:
                    _gr[_g]=_gr.get(_g,0)+1
            _rep=[k for k,v in sorted(_gr.items(),key=lambda x:-x[1]) if v>=3][:6]
            if _rep: print('  ℹ⑯复读哨兵(第%d章,≥3次四字串,AI裁回声或灌):'%n,'、'.join(_rep))
            _dur=[m.group() for m in re.finditer(r'半年|[一二两三四五六七八九十]+个月|整整[一二三]年',_bt)]
            if _dur: print('  ℹ⑰时长断言哨兵(第%d章,逐条对时间卡):'%n,'、'.join(sorted(set(_dur))))
            _RT=('那年','那一夜','那晚','上一回','后来在','我在','想起','我认得','见过','试过','头一回')
            _flag=[]
            for _s in re.split(r'(?<=[。！？])',_bodyx(t)):
                if any(k in _s for k in _RT) and re.search(r'[在][^，。]{1,8}[里上外前]|[一二三四五六七八九十]{1,3}[个字步声年天]',_s):
                    _flag.append(_s.strip()[:34])
            if _flag:
                print('  ⚠⑲回述实证哨兵(第%d章·A级防线):以下句含"前章事件＋具体地点/数字",'%n)
                print('     落笔前必须grep原场逐字比对,回执须贴原文;凭印象=伪造记忆(铁律一A级)')
                for _x in _flag[:6]: print('       ·',_x)
            if _new: print('  ℹ⑮新锚候选(第%d章,AI须逐条裁决钉入/豁免并写入回执):'%n,'、'.join(_new))
        if n==max(files):
            for _x in due_report(n, as_gate=True):
                pr.append('到期账逾期%d章未清: [%s] %s（限第%d章）——须先清账或在到期账改期并记因' % (n-_x['到期章'],_x['id'],_x['事'],_x['到期章']))

        if n==max(files):

            try:

                import io,contextlib

                _buf=io.StringIO()

                with contextlib.redirect_stdout(_buf): _dg=diff_gate(n)

                if _dg: pr.append('改动闸机械层未清零(工作区较HEAD的变动段含破折/半角/英文/五逗/禁词)：%s——清零后再封版'%('；'.join(_l.strip() for _l in _buf.getvalue().splitlines() if '⛔' in _l)[:240] or '见改动闸之报'))

            except Exception: pass


        if n==max(files) and n>=73 and not _receipt_ok(n):
            if _in_progress(n):
                print('  ℹ第%d章在跑（十轮未满、回执按例未交）：回执闸暂不计硬错（批130）；'
                      '十轮跑毕交回执时此闸自然复位。' % n)
            else:
                # 〔1119 死规之审·gates14〕回执闸已拔「五钩」之键，报文同去之
                pr.append('回执未交:当章《检察官回执》未在设定/回执_*.md归档(须含本章标记+伏笔裁决+诸键)——回执未交禁止封版')
        if n>=153 and _receipt_filed(n):
            _rf=_rounds_full(n)
            if _rf: pr.append(_rf)
            _zh=_zonghe_ok(n)
            if _zh: pr.append(_zh)
        _rv=rhythm_violation(files[n][2],n,_rhythm_exempt(n))
        if _rv: pr.append(_rv)
        _rr=rhythm_review(files[n][2],n,_rhythm_exempt(n))   # 〔1119 死规之审·gates13〕无长段只印 REVIEW、⛔入 pr（只 90 分位之红入硬错）
        if _rr: print('  ?第%d章 %s'%(n,_rr))
        if weight_violation(wc,n,_short_ch_exempt(n)):
            pr.append(f'跌破铁底:全章{wc}字<2000(唯一硬线·质量优先严禁凑字);如确属短章,须在施工表登记\u201c第 {n} 章短章豁免\u201d并说明理由(2026-07-17反向闸)')
        if pr: ERR+=len(pr); print(f'  ✗第{n}章《{nm}》:'); [print('     ',x) for x in pr]
    if ERR==0: print('  ✓ 全部通过')
    if not focus:
        for fa in lib['facts']:
            if fa.get('level')=='FYI':
                tot={n:sum(len(re.findall(p,files[n][2])) for p in fa['forbid']) for n in tg if n in files}
                tot={k:v for k,v in tot.items() if v}
                if tot: print(f'  ℹ [{fa["id"]}]:',dict(sorted(tot.items())))
    return ERR


def ai_homework(n,files):
    f,nm,t=files[n]
    t=re.sub(r'^.*?第.+?章[^\n]*\n','',t,count=1,flags=re.S)
    print(); print('═'*50); print(f'  ◆ 检察官指令→AI · 第{n}章《{nm}》必答作业单 ◆'); print('═'*50)
    print('【一·绝对化逐条对照】声称"首次"的,前文若已出现=硬伤:')
    c=0
    for pt in ['第一次','头一回','头一遭','从没','从未','这辈子头','平生']:
        for m in re.finditer(pt,t):
            c+=1; print(f'   {c:02d}. 行{_ln(t,m.start())} …{t[max(0,m.start()-14):m.end()+30]}…'.replace(chr(10),'␤'))
    if c==0: print('   (无)')
    print('【二·回述句贴原文比对】凡"想起/记得/当日/那晚"必逐字对照原场,只可补白不可改写:')
    c=0
    for s in re.split(r'(?<=[。！？…])',t):
        if any(k in s for k in ['想起','我记得','当日','那晚','那一夜','那时候','后来我才']) and len(s)>10:
            c+=1; print(f'   {c:02d}.',s.strip()[:56]+('…' if len(s)>58 else ''))
            if c>=12: break
    if c==0: print('   (无)')
    print('【三·数字负向核账+经济配位】数字对canon(年龄23/年份2006/台阶27级/日期2-17);大宗交易价对年代(2006:骆驼数千元一峰/报纸五毛/白酒二十/悬赏十万)——一粒米吃不饱:')
    c=0
    for m in re.finditer(r'[一二三四五六七八九十百千两〇0-9]{1,6}(?:年|个?月|日|级|天|里|岁|口|峰|捆|块|丈|步|宿|张)',t):
        c+=1; print(f'   {c:02d}. 行{_ln(t,m.start())} …{t[max(0,m.start()-10):m.end()+8]}…'.replace(chr(10),'␤'))
        if c>=22: break
    if c==0: print('   (无)')
    print('【四·因果配位(1+1=2式惊叹审计)】凡惊叹/称奇/断稀罕,自问:平常人能不能轻易做到?证据配得上结论吗?')
    c=0
    for m in re.finditer(r'(竟然|居然|这才是|好一手|何等|没有第二|只有他|世上少有|稀罕物)',t):
        c+=1; print(f'   {c:02d}. 行{_ln(t,m.start())} …{t[max(0,m.start()-12):m.end()+22]}…'.replace(chr(10),'␤'))
        if c>=10: break
    if c==0: print('   (无)')
    print('【五·台词绝对化审计】"头一句/三天没说话/一路没开口"类,须核:该人物该时段真沉默否?与其机敏在场人设冲突否?(61章"三天头一句整话"撞老头机敏=硬伤)')
    c=0
    for m in re.finditer(r'(头一句|第一句|头一回[开吭]|三[天日]里[^\n]{0,4}[话句]|一路[没不][开说]过|多少[天日][没不][开说])',t):
        c+=1; print(f'   {c:02d}. 行{_ln(t,m.start())} …{t[max(0,m.start()-14):m.end()+22]}…'.replace(chr(10),'␤'))
        if c>=8: break
    if c==0: print('   (无)')
    print('【六·地名/道具语义一致性】关键地点服从首次完整原场；道具能力不得越界:')
    concept={'柏冢':'墓葬地点，绝非老宅地窖；入口史服从首次完整原场','老宅地窖':'守灵夜开启，发现先祖古尸并取走另一半玉','血图':'提供目的地/墓址信息，不规划路线','玉':'只以温度响应同源浓源；不测普通危险，不位移或规划路线；白光须跨过强接苏衍鼎心联结的窄门'}
    c=0
    for k,v in concept.items():
        for m in re.finditer(k,t):
            c+=1; print(f'   {c:02d}. [{k}={v}] 行{_ln(t,m.start())} …{t[max(0,m.start()-12):m.end()+20]}…'.replace(chr(10),chr(9)))
            break
    if c==0: print('   (本章无关键地名/概念)')
    else: print('   ⚠AI须逐个裁定:地点是否被混写?玉是否被误写成敌意雷达或导航仪?')
    roster_eye(n,files)
    title_eye(n,files)
    print('【七·封神三问+九轮】高光在哪一句?全局位置对不对?读者翻不翻页?九轮逐关走查。')
    statecard(n)
    cardiogram(n,files)
    pageturn(n,files)
    foreshadow_report(slice_for=n)
    print('─'*50)
    print('  回执义务:AI必须以"检察官回执"逐项作答(合/违+修),未回执不得封版。')

