# 剧情 beat 不入机器：唯一权威是总圣经；机器只递情报，不替正文发明事实。
def _paras(body): return [x.strip() for x in re.split(r'\n\s*\n',body) if x.strip()]
def cardiogram(n,files):
    f,nm,t=files[n]; body=re.sub(r'^.*?第.+?章[^\n]*\n','',t,count=1,flags=re.S)
    ps=_paras(body)
    print('【八·章内心电图+感官配比】(机器测,AI裁节奏病)')
    lens=[len(re.findall(r'[\u4e00-\u9fff]',x)) for x in ps]
    bar=''.join('▁▂▃▄▅▆▇█'[min(7,l//22)] for l in lens)
    print(f'   段长心电:{bar}  段数{len(ps)} 均{sum(lens)//max(1,len(lens))}字 峰{max(lens)} 谷{min(lens)}')
    import statistics
    sents=[s for s in re.split(r'(?<=[。！？…])',body) if s.strip()]
    slens=[len(s) for s in sents]
    print(f'   句长方差:{int(statistics.pvariance(slens)) if len(slens)>1 else 0}(过小=节奏平;>900=忽长忽短审)')
    sense={'视':'看|望|见|瞧|盯|瞥|色|光|影','听':'听|响|声|鸣|吼|嘶|静','触':'烫|凉|冷|暖|湿|疼|麻|颤|贴','嗅':'味|气|腥|香|臭|嗅'}
    cc={k:sum(len(re.findall(w,body)) for w in v.split('|')) for k,v in sense.items()}
    print('   感官配比:',' '.join(f'{k}{v}' for k,v in cc.items()),'←嗅触≪视听=平面感,酌情补体感')
    from collections import Counter
    bg=Counter(body[i:i+2] for i in range(len(body)-1) if re.match(r'[\u4e00-\u9fff]{2}',body[i:i+2]))
    stop={'我们','他们','一个','没有','什么','就是','这个','那个','的一','一样','出来','起来','是一','了一','这一','都是','自己','一句','一点','那些','这些','里的','上的','一眼'}
    top=[(w,c) for w,c in bg.most_common(40) if w not in stop and c>=6][:6]
    heads=[x[0] for x in ps if x]
    run=1;mx=1
    for i in range(1,len(heads)):
        run=run+1 if heads[i]==heads[i-1] else 1
        mx=max(mx,run)
    if mx>=4: print(f'   段首复读:同一开头字连排{mx}段(如我我我…),审是否催眠')
    if top: print('   高频双字:',' '.join(f'{w}×{c}' for w,c in top),'←≥6次者自审是否口头禅')
def _story_only(t):
    """切掉封版之後贴在文件尾巴上的台账，只留小说本身。

    ★立此法之由（2026-09-03·对位闸所逮）：`--封版 293` 实跑，五钩之「收尾三段」印的是
      「★★★而其数：第一百零四天｜十层一样长…」——**那是台账，不是小说的结尾**
      （293 真末句在第373行「而那一排点，明天还是六个。」）。
      **一件量结尾之钩的器，读的是台账；於是它两百多章一直在给台账打分。**
    ★★其界：`【本章亮点】`（全书294章中188章有之；无之者多系早章，其全文即正文，故原样返回）。
    """
    i = t.find('【本章亮点】')
    return t[:i] if i > 0 else t


def pageturn(n,files):
    f,nm,t=files[n]; body=re.sub(r'^.*?第.+?章[^\n]*\n','',_story_only(t),count=1,flags=re.S)
    ps=_paras(body)
    # 〔1119 死规之审·gates14〕删「<7二选一:补钩」：分低⛔逼补钩（每章硬塞钩违 1119·G1108-06）；评分照打、静章合法留
    print('【九·翻页力五钩评分】(AI必打分必答:钩/新问/情绪波/危机升档/承诺推进 各0-2。静水深流合法,59《不像他》即无钩神品。闸在必答,不在分数)')
    print('   开篇两段:',' ␤ '.join(x[:38] for x in ps[:2]))
    print('   收尾三段:',' ␤ '.join(x[:38] for x in ps[-3:]))
    tail=''.join(ps[-3:])
    sig=[]
    if '？' in tail: sig.append('问号钩✓')
    if re.search(r'(等|来了|醒|晚了|开始|没完|藏着|望着我)',tail): sig.append('威胁/悬念词✓')
    if not sig: sig.append('⚠机器未探到尾钩,AI严审是否哑弹')
    print('   机器初探:',' '.join(sig))
def foreshadow_report(upto=999,slice_for=None):
    lib=_load_lib()
    fs=lib.get('foreshadows',[])
    if slice_for is not None:
        due=[x for x in fs if x['status']=='open' and x['due']<=slice_for+3]
        if due:
            print('【十·伏笔账本·到期/临期】(AI回执三选一裁决:接/展期/废弃,当场登记;严禁硬插凑数,也严禁无声蒸发)')
            for x in due:
                mark='‼逾期' if x['due']<slice_for else ('★本章到期' if x['due']<=slice_for else '临期')
                print(f"   {x['id']} 植于{x['plant']}章|限{x['due']}章|{mark}|{x['desc']}")
        else: print('【十·伏笔账本】本章窗口无到期账(仍须自查有无新埋→登记)')
        return
    print('══════ 伏笔账本(全) ══════')
    for x in fs:
        st='✓已清' if x['status']=='paid' else ('‼逾期' if x['due']<upto else '○在押')
        print(f" {x['id']}|{st}|植{x['plant']}→限{x['due']}|{x['desc']}")
    op=[x for x in fs if x['status']=='open']
    print(f' 合计:{len(fs)}根,在押{len(op)},逾期{sum(1 for x in op if x["due"]<upto)}')
def statecard(n):
    lib=_load_lib()
    rel=[x for x in lib.get('state_canon',[]) if x['from']<=n]
    if rel:
        print('【状态卡·已登记状态(机器复述,执笔必对表)】')
